```java
// ─── File: SingletonDemo.java ───
package com.bank.singleton;

import java.util.*;
import java.util.logging.Logger;

class ConfigManager {
    private final Map<String, String> settings = new HashMap<>();
    private ConfigManager() {                         // private constructor: no external 'new'
        settings.put("bank.name", "National Bank of India");
        settings.put("pool.size", "10");
    }
    private static class Holder {                     // lazy + thread-safe via class loading
        static final ConfigManager INSTANCE = new ConfigManager();
    }
    static ConfigManager getInstance() { return Holder.INSTANCE; }
    String get(String key) { return settings.get(key); }
}

class ConnectionPool {
    private final List<String> connections = new ArrayList<>();
    private ConnectionPool() {
        int size = Integer.parseInt(ConfigManager.getInstance().get("pool.size"));
        for (int i = 0; i < size; i++) connections.add("conn-" + i);
    }
    private static class Holder { static final ConnectionPool INSTANCE = new ConnectionPool(); }
    static ConnectionPool getInstance() { return Holder.INSTANCE; }
    int available() { return connections.size(); }
}

public class SingletonDemo {
    public static void main(String[] args) {
        Logger log = Logger.getLogger("SINGLETON");
        ConfigManager a = ConfigManager.getInstance();
        ConfigManager b = ConfigManager.getInstance();
        log.info("Same config instance? " + (a == b));           // true
        log.info("Bank name = " + a.get("bank.name"));
        log.info("Pool connections = " + ConnectionPool.getInstance().available());
    }
}
```
